\title{The Residue-Leakage Curve and the \\ Dirichlet No-Pruning Theorem}
\author{Aristotle}
\date{13 August 2026}

\begin{document}
\maketitle

\begin{abstract}
For a finite list $A=(a_1,\dots,a_K)$ of probe primes, the \emph{quadratic-residue
fingerprint} of an integer $N$ is the vector of Jacobi symbols
$\FA(N)=\bigl(\jac{a_1}{N},\dots,\jac{a_K}{N}\bigr)$. Each entry is computable in
$\mathrm{poly}(\log N)$ time with no factorization of $N$, so $\FA$ is the maximal
\emph{cheap} residue handle attached to $N$. We determine exactly what this handle
knows about a factorization $N_0=pq$.

Our principal result is the \emph{Dirichlet No-Pruning Theorem}: for every odd
target $N_0$ coprime to the probes and every odd prime $p$ outside the probe set
there are infinitely many primes $q$ with $\FA(pq)=\FA(N_0)$. Every candidate prime
factor is consistent with the observation; the fingerprint prunes nothing. We
isolate the arithmetic core --- the compensators are \emph{precisely} the primes of
the unit class $N_0p$ modulo the conductor $4\prod A$ --- so that any effective
bound for the least prime in a coprime class transfers verbatim, yielding a
constructive form. We further prove that every one of the $2^K$ sign vectors is the
fingerprint of infinitely many primes; that consistency of a pair $(p,q)$ is
\emph{equivalent} to the single symmetric relation
$\jac{a}{q}=\jac{a}{N_0}\jac{a}{p}$, whence the factorization fibre is a coset of
the anti-diagonal of $\{\pm1\}^K\times\{\pm1\}^K$, a trivial torsor under it, of
size exactly $2^K$, surjecting onto the first coordinate; and that the only pruning
the channel ever achieves is detecting a probe-sized prime factor. Finally we show
the obstruction holds for every finite family of Dirichlet characters of fixed
modulus, persists at the level of conjugacy classes in every group (while the
torsor structure holds if and only if the group is abelian), and is
sieve-independent: any sound candidate filter accepts every admissible candidate.
\end{abstract}

\medskip
\noindent\textbf{Keywords:} Jacobi symbol; quadratic residues; Dirichlet's theorem
on arithmetic progressions; Dirichlet characters; integer factorization;
information leakage; torsor; Artin symbol.

\section{Introduction}

\subsection{The question}

Let $N_0=pq$ be a semiprime with unknown factorization. A small classical family of
questions may be asked about $N_0$ without factoring it, chief among them questions
of quadratic character: for a small prime $a$, the Jacobi symbol $\jac{a}{N_0}$ is
computable by a reciprocity-driven Euclidean algorithm in time
$\mathrm{poly}(\log N_0)$, with value in $\{+1,-1\}$ whenever $\gcd(a,N_0)=1$.

Collecting these answers over the first $K$ primes produces a $K$-bit fingerprint.
Empirically the fingerprint is strikingly discriminative: on a sample of three
hundred cryptographic-shape semiprimes, $K=20$ probes separate all three hundred
targets without collision. The natural conjecture is that so much cheap structured
information must constrain the factors --- that some candidate primes can be ruled
out because no partner could reproduce the observed symbols. This paper proves the
conjecture false in the strongest possible sense and determines the exact
information-theoretic content of the channel.

\subsection{Summary of results}

Throughout, $A$ is a finite list of distinct probe primes, $K=|A|$, and
$\FA(N)=\bigl(\jac{a}{N}\bigr)_{a\in A}$.

\begin{itemize}
\item \textbf{Theorem A} (No pruning, Thm.~\ref{thm:nopruning}). For odd $N_0$
coprime to $A$ and any odd prime $p\notin A$, the set
$\{q \text{ prime}: \FA(pq)=\FA(N_0)\}$ is infinite.
\item \textbf{Theorem B} (Compensating class; effective form,
Thms.~\ref{thm:class}--\ref{thm:effective}). Every prime $q\equiv N_0p
\pmod{4\prod A}$ compensates, and $N_0p$ is a unit modulo $4\prod A$.
\item \textbf{Theorem C} (Pattern surjectivity, Thm.~\ref{thm:surj}). Every sign
vector in $\{\pm1\}^K$ is the fingerprint of infinitely many primes; the range of
$\FA$ on primes outside $A$ has cardinality exactly $2^K$.
\item \textbf{Theorem D} (Exact consistency; coset and torsor,
Thms.~\ref{thm:consistency}--\ref{thm:fibresize}).
\item \textbf{Theorem E} (Sharp boundary, Thm.~\ref{thm:boundary}).
\item \textbf{Theorem F} (Abelian channels, Thm.~\ref{thm:abelian}).
\item \textbf{Theorem G} (Non-abelian channels,
Thms.~\ref{thm:nonab}--\ref{thm:eltfibre}).
\item \textbf{Theorem H} (Sieve independence, Thm.~\ref{thm:filter}).
\end{itemize}

\subsection{Interpretation}
The channel emits exactly $K$ bits about $N$ and exactly $0$ bits about the
factorization. Discriminative power and pruning power are entirely decoupled: the
residue channel identifies the haystack and says nothing about the needle.

\section{Definitions and basic structure}

\begin{definition}[Probe list, fingerprint]
A \emph{probe list} is a finite list $A=(a_1,\dots,a_K)$ of distinct primes. The
\emph{quadratic-residue fingerprint} of $N\in\mathbb{N}$ relative to $A$ is
\[
\FA(N)=\bigl(\jac{a_1}{N},\dots,\jac{a_K}{N}\bigr),
\]
where $\jac{\cdot}{\cdot}$ is the Jacobi symbol. Entries lie in $\{+1,-1\}$ when
$\gcd(a,N)=1$ and vanish otherwise.
\end{definition}

\begin{definition}[Conductor]
The \emph{conductor} of $A$ is $M_A=4\prod_{a\in A}a$. If $2\in A$ this is the
classical $8\prod_{a \text{ odd}}a$.
\end{definition}

\begin{definition}[Admissible candidate]
For a probe list $A$, a natural number $p$ is an \emph{admissible candidate} if $p$
is an odd prime with $p\notin A$.
\end{definition}

\begin{proposition}[Multiplicativity]\label{prop:mult}
For nonzero $m,n$ we have $\FA(mn)=\FA(m)\odot\FA(n)$, the entrywise product.
\end{proposition}

\begin{proof}
Entrywise this is $\jac{a}{mn}=\jac{a}{m}\jac{a}{n}$, applied along the list.
\end{proof}

This is the \emph{symmetric residue structure} leaked by a semiprime: the
observation determines the products $\jac{a}{p}\jac{a}{q}$ and nothing more.
Everything below is a precise elaboration of ``nothing more''.

\begin{proposition}[Periodicity]\label{prop:period}
If $m,n$ are odd and $m\equiv n \pmod{M_A}$, then $\FA(m)=\FA(n)$.
\end{proposition}

\begin{proof}
For each probe $a$ we have $4a\mid M_A$, hence $m\equiv n\pmod{4a}$; on odd
arguments the symbol $\jac{a}{\cdot}$ depends only on the class modulo $4a$ (by
quadratic reciprocity together with the supplementary law at $2$).
\end{proof}

\begin{proposition}[Square-class invariance]\label{prop:sqclass}
If $m,s\neq 0$ and no probe divides $s$, then $\FA(ms^2)=\FA(m)$.
\end{proposition}

\begin{proof}
$\jac{a}{ms^2}=\jac{a}{m}\jac{a}{s}^2$ and $\jac{a}{s}=\pm1$ since $a\nmid s$.
\end{proof}

Propositions~\ref{prop:period} and \ref{prop:sqclass} already refute the
``collision-free hash'' reading of the experimental data: $\FA$ factors through
$(\mathbb{Z}/M_A)^\times/\bigl((\mathbb{Z}/M_A)^\times\bigr)^2$, a group of order at
most $2^{K+1}$. Three hundred distinct values among $2^{20}$ possibilities is a
birthday-paradox non-event.

\begin{lemma}\label{lem:coprime}
If $m$ is odd and coprime to every probe, then $\gcd(m,M_A)=1$.
\end{lemma}

\section{The Dirichlet realization lemma}

\begin{lemma}[Dirichlet realization]\label{lem:realize}
Let $A$ be a probe list and $m$ odd and coprime to every probe. Then
\[
\{\, q \text{ prime}: q \text{ odd and } \jac{a}{q}=\jac{a}{m} \text{ for all } a\in A \,\}
\]
is infinite.
\end{lemma}

\begin{proof}
Let $M=M_A$. By Lemma~\ref{lem:coprime}, $m$ is a unit mod $M$. Dirichlet's theorem
supplies infinitely many primes $q\equiv m \pmod M$. Since $2\mid M$ and $m$ is odd,
each such $q$ is odd; since $4a\mid M$ for each probe, the entrywise argument of
Proposition~\ref{prop:period} gives $\jac{a}{q}=\jac{a}{m}$.
\end{proof}

\begin{corollary}[The fingerprint is not a hash]\label{cor:nothash}
For $m$ odd and coprime to the probes, $\{q \text{ prime}: \FA(q)=\FA(m)\}$ is
infinite: every realized fingerprint class contains infinitely many primes.
\end{corollary}

Structurally, each fingerprint entry is a Dirichlet character of
$(\mathbb{Z}/M_A)^\times$, and Dirichlet's theorem populates every unit class with
infinitely many primes. All impossibility results below are this one fact seen from
different angles.

\section{The No-Pruning Theorem}

\begin{theorem}[Dirichlet No-Pruning]\label{thm:nopruning}
Let $A$ be a probe list, $N_0$ odd and coprime to every probe, and $p$ an odd prime
with $p\notin A$. Then $\{\,q \text{ prime}: \FA(pq)=\FA(N_0)\,\}$ is infinite.
Consequently the observation $\FA(N_0)$ removes \emph{no} candidate prime $p$ from
the divisor search.
\end{theorem}

\begin{proof}
Put $m=N_0p$: it is odd, and coprime to each probe ($N_0$ by hypothesis, $p$ because
it is a prime distinct from every probe). Lemma~\ref{lem:realize} gives infinitely
many odd primes $q$ with $\jac{a}{q}=\jac{a}{m}$ for all $a\in A$. For any such $q$
and any probe $a$,
\[
\jac{a}{pq}=\jac{a}{p}\jac{a}{q}=\jac{a}{p}\jac{a}{N_0p}
=\jac{a}{N_0}\jac{a}{p}^2=\jac{a}{N_0},
\]
using Proposition~\ref{prop:mult} twice and $\jac{a}{p}^2=1$ (valid since $a\neq p$
are distinct primes). Hence $\FA(pq)=\FA(N_0)$.
\end{proof}

\subsection{The arithmetic core, and effectivity}

\begin{lemma}\label{lem:unitclass}
Under the hypotheses of Theorem~\ref{thm:nopruning}, $\gcd(N_0p,M_A)=1$.
\end{lemma}

\begin{theorem}[The compensating set is a full unit class]\label{thm:class}
Under the hypotheses of Theorem~\ref{thm:nopruning}, \emph{every} prime $q$ with
$q\equiv N_0p \pmod{M_A}$ satisfies $\FA(pq)=\FA(N_0)$.
\end{theorem}

\begin{proof}
Since $2\mid M_A$ and $N_0p$ is odd, $q$ is odd. Since $4a\mid M_A$ for each probe
$a$, the congruence gives $\jac{a}{q}=\jac{a}{N_0p}$, and the computation in the
proof of Theorem~\ref{thm:nopruning} applies verbatim. No appeal to Dirichlet is
made: this is a pure congruence statement.
\end{proof}

\begin{theorem}[Effective no-pruning]\label{thm:effective}
Suppose $B$ bounds the least prime in every coprime residue class modulo $M_A$.
Then for every candidate prime $p$ there is a compensating prime $q\le B$ with
$\FA(pq)=\FA(N_0)$.
\end{theorem}

\begin{proof}
Apply the hypothesis to the unit class $N_0p$ (Lemma~\ref{lem:unitclass}) and then
Theorem~\ref{thm:class}.
\end{proof}

Linnik's theorem provides such a $B$ of the shape $C\cdot M_A^{L}$. Since $M_A$ is a
fixed small modulus for any practical $K$, the compensating witness is constructible
in polynomial time: the defeat of the residue sieve is effective.

