function JACOBI(a, n):                       # n odd, n >= 1
    a <- a mod n ;  result <- 1
    while a != 0:
        while a is even:
            a <- a / 2
            if n mod 8 in {3, 5}: result <- -result     # supplementary law at 2
        swap(a, n)                                       # reciprocity
        if a mod 4 = 3 and n mod 4 = 3: result <- -result
        a <- a mod n
    if n = 1: return result else return 0                # gcd(a,n) > 1

function FINGERPRINT(A, N):
    return [ JACOBI(a, N) for a in A ]

function CONDUCTOR(A):
    return 4 * product(A)

function COMPENSATING_CLASS(A, N0, p):
    M <- 4 * product(A)
    return ( (N0 * p) mod M , M )              # a unit class, since gcd(N0*p, M)=1

function FIND_COMPENSATING_PRIME(A, N0, p):
    (r, M) <- COMPENSATING_CLASS(A, N0, p)
    observed <- FINGERPRINT(A, N0)
    q <- r if r > 1 else r + M
    loop:
        if IS_PRIME(q) and q != p and q not in A:
            if FINGERPRINT(A, p*q) = observed: return q
        q <- q + M                              # stay inside the unit class

function CERTIFY_NO_PRUNING(A, N0, candidates):
    for p in candidates:
        q <- FIND_COMPENSATING_PRIME(A, N0, p)
        assert FINGERPRINT(A, p*q) = FINGERPRINT(A, N0)   # p survives

function LEAST_NONRESIDUE(a):                  # a an odd prime
    for r = 2, 3, ... :
        if r^((a-1)/2) = -1 (mod a): return r  # Euler's criterion

function PATTERN_MODULUS(A, eps):
    x, mod <- (1 if eps(2) = +1 else 5), 8     # supplementary law at 2
    for a in A, a odd:
        residue <- 1 if eps(a) = +1 else LEAST_NONRESIDUE(a)
        (x, mod) <- CRT(x, mod, residue, a)
    return x mod mod                           # satisfies x = 1 (mod 4)

function PRIME_WITH_PATTERN(A, eps):
    M <- 4 * product(A)
    q <- PATTERN_MODULUS(A, eps) mod M
    loop:
        if IS_PRIME(q) and q not in A and FINGERPRINT(A, q) = eps: return q
        q <- q + M
